@Override
public boolean appliesTo(@NonNull ResourceFolderType folderType) {
    return true; // collect locales from all resource folders
}

@Override
public void checkFolder(@NonNull ResourceContext context, @NonNull ResourceFolder folder) {
    FolderConfiguration config = folder.getConfiguration();
    String locale = getLocaleString(config);
    if (locale != null) {
        mAllLocales.add(locale);
    }
    if (folder.getType() == ResourceFolderType.DRAWABLE) {
        Set<String> names = mDrawableFilesByLocale.get(locale != null ? locale : "");
        if (names == null) {
            names = new HashSet<>();
            mDrawableFilesByLocale.put(locale != null ? locale : "", names);
        }
        for (ResourceFile file : folder.getFiles()) {
            String fileName = file.getName();
            int dot = fileName.lastIndexOf('.');
            String baseName = dot > 0 ? fileName.substring(0, dot) : fileName;
            names.add(baseName);
        }
    }
}

private static String getLocaleString(FolderConfiguration config) {
    if (config == null) return null;
    LocaleQualifier locale = config.getLocaleQualifier();
    if (locale == null || (!locale.hasLanguage() && !locale.hasRegion())) return null;
    return locale.getValue(); // or toString()
}
```
